CREATE TABLE cms.cms_scheduled_publications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), content_item_id UUID NOT NULL REFERENCES cms.cms_content_items(id), content_revision_id UUID NOT NULL REFERENCES cms.cms_content_revisions(id), scheduled_at TIMESTAMPTZ(6) NOT NULL, time_zone VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, created_by_user_id UUID NOT NULL, created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
